(() => {
  const $=id=>document.getElementById(id);let expanded=false;NekoSurfaceBridge.makeDraggable($('dockHandle'));
  NekoSurfaceBridge.listen(({type,payload})=>{if(type==='state'){$('state').textContent=payload.state.toUpperCase();$('tasks').textContent=`${payload.tasks} / ${payload.total}`;$('failures').textContent=payload.failures;$('confidence').textContent=payload.confidence===null?payload.level:`${payload.confidence===100?'':'~'}${payload.confidence}% · ${payload.level}`;$('lines').replaceChildren(...payload.lines.map(text=>{const li=document.createElement('li');li.textContent=text;return li;}));}if(type==='preferences'){$('attach').textContent=payload.attached?'Following Neko':'Attach to Neko';$('attach').setAttribute('aria-pressed',String(payload.attached));}});
  $('hide').onclick=()=>NekoSurfaceBridge.send('dock-hide');$('attach').onclick=()=>NekoSurfaceBridge.send('dock-attach');$('expand').onclick=()=>{expanded=!expanded;$('activity').hidden=!expanded;$('expand').textContent=expanded?'Less ↑':'Details ↓';$('expand').setAttribute('aria-expanded',String(expanded));};new ResizeObserver(()=>NekoSurfaceBridge.send('resize',{height:$('dock').offsetHeight+2})).observe($('dock'));NekoSurfaceBridge.send('ready');
})();
